package org.slavicmyths.client;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.nbt.CompoundTag;
import org.slavicmyths.sivka.*;

/** Actual native geometry and ledger codecs without starting Minecraft. */
public final class SivkaChecks {
    static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    static java.lang.reflect.Field cubes,children,polygons;
    static JsonArray export(ModelPart p,String path,float x,float y,float z)throws Exception{x+=p.x;y+=p.y;z+=p.z;var out=new JsonArray();for(var raw:(List<?>)cubes.get(p)){var c=(ModelPart.Cube)raw;check(c.maxX>c.minX&&c.maxY>c.minY&&c.maxZ>c.minZ,"positive mesh "+path);var j=new JsonObject();j.addProperty("part",path);j.add("min",new Gson().toJsonTree(new float[]{x+c.minX,y+c.minY,z+c.minZ}));j.add("max",new Gson().toJsonTree(new float[]{x+c.maxX,y+c.maxY,z+c.maxZ}));var faces=new JsonArray();for(Object face:(Object[])polygons.get(c)){if(face==null)continue;var vf=face.getClass().getDeclaredField("vertices");vf.setAccessible(true);var coords=new JsonArray();for(Object v:(Object[])vf.get(face)){var u=v.getClass().getDeclaredField("u");var a=v.getClass().getDeclaredField("v");var pos=v.getClass().getDeclaredField("pos");u.setAccessible(true);a.setAccessible(true);pos.setAccessible(true);float uu=u.getFloat(v),vv=a.getFloat(v);check(uu>=0&&uu<=1&&vv>=0&&vv<=1,"UV "+path);var at=(org.joml.Vector3f)pos.get(v);coords.add(new Gson().toJsonTree(new float[]{x+at.x,y+at.y,z+at.z,uu,vv}));}faces.add(coords);}j.add("faces",faces);out.add(j);}for(var entry:((Map<String,ModelPart>)children.get(p)).entrySet())for(var c:export(entry.getValue(),path+"/"+entry.getKey(),x,y,z))out.add(c);return out;}
    public static void main(String[] args)throws Exception{
        for(int ticks=0;ticks<60;ticks++)for(double speed:new double[]{0,8.99,9,12})check(SivkaRules.ready(speed,ticks,true,true)==true,"takeoff no long runway; sprint+ground gate");check(!SivkaRules.ready(12,50,false,true)&&!SivkaRules.ready(12,50,true,false),"ground and sprint mandatory");
        double speed=0;for(int t=0;t<60;t++)speed=SivkaRules.approach(speed,12,4./20);check(Math.abs(speed-12)<1e-8,"3 second acceleration");double sum=0;for(int i=0;i<1440;i++){double wave=SivkaRules.physicalWave(i/1440.);sum+=wave;check(Math.abs(wave)<=.0250001,"camera-safe micro wave");}check(Math.abs(sum)<1e-8,"zero-mean altitude wave");
        for(boolean air:new boolean[]{false,true})for(int col=1;col<=8;col++){check(Math.abs(SivkaPoses.sample(air,0,col)-SivkaPoses.sample(air,1,col))<.001,"loop seamless");for(int i=0;i<100;i++)check(Float.isFinite(SivkaPoses.sample(air,i/100F,col)),"finite poses");}
        var data=new SivkaBonds();var b=new SivkaBonds.Bond(UUID.randomUUID());b.stage=4;b.play=900;b.expiry=72900;b.entity=UUID.randomUUID();b.dimension="minecraft:the_nether";b.generation=9;b.token=3;b.health=57;b.recovery=1300;data.bonds.put(b.owner,b);var n=data.save(new CompoundTag(),null);var copy=SivkaBonds.load(n.copy(),null);check(n.equals(copy.save(new CompoundTag(),null)),"actual ledger codec roundtrip");check(b.valid(),"temporary active");b.expired=true;check(!b.valid()&&b.stage==4,"expiry preserves progress");b.stage=7;check(b.valid(),"permanent timer-free");
        cubes=ModelPart.class.getDeclaredField("cubes");children=ModelPart.class.getDeclaredField("children");polygons=ModelPart.Cube.class.getDeclaredField("polygons");cubes.setAccessible(true);children.setAccessible(true);polygons.setAccessible(true);var model=SivkaMesh.create();model.y=24;var exported=export(model,"sivka",0,0,0);float min=100,max=-100;for(var c:exported){var j=c.getAsJsonObject();min=Math.min(min,j.getAsJsonArray("min").get(1).getAsFloat());max=Math.max(max,j.getAsJsonArray("max").get(1).getAsFloat());}check(exported.size()>=120,"dedicated detailed silhouette");check((24-min)/16>=2.7&&(24-min)/16<=3.1,"standing height: "+(24-min)/16);check(Math.abs(max-24)<2,"hooves near native ground");check(SivkaMesh.index(model).size()>=50,"articulated rig");var json=new JsonObject();json.add("sivka",exported);Files.writeString(Path.of("work/sivka/meshes.json"),new GsonBuilder().setPrettyPrinting().create().toJson(json));System.out.println("SIVKA OFFLINE PASS: "+checks+" checks; height="+(24-min)/16+", cubes="+exported.size()+". Game launches: 0; codec is not real relog.");
    }
}
